document.querySelectorAll(".wm-product-specs[data-mobile-ready], .wm-product-specs--mobile-collapsed, .wm-product-specs--mobile-expanded").forEach(function(e){var t=e.querySelectorAll("[data-specs-toggle]");t.length&&t.forEach(function(c){c.addEventListener("click",function(){var c=e.classList.contains("wm-product-specs--mobile-expanded");e.classList.toggle("wm-product-specs--mobile-expanded",!c),e.classList.toggle("wm-product-specs--mobile-collapsed",c),t.forEach(function(e){e.setAttribute("aria-expanded",c?"false":"true")})})})}),document.querySelectorAll("[data-mobile-description]").forEach(function(e){var t=e.querySelectorAll("[data-description-toggle]");t.length&&t.forEach(function(c){c.addEventListener("click",function(){var c=e.classList.contains("wm-product-description--expanded");e.classList.toggle("wm-product-description--expanded",!c),e.classList.toggle("wm-product-description--collapsed",c),t.forEach(function(e){e.setAttribute("aria-expanded",c?"false":"true")})})})});